-- Idempotent ACL reconciliation for schema-only HR.sys staging.
BEGIN;
REVOKE ALL ON FUNCTION public.admin_get_user_email(uuid), public.admin_update_user_credentials(uuid,text,text) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.admin_get_user_email(uuid), public.admin_update_user_credentials(uuid,text,text) TO authenticated;
GRANT SELECT, INSERT, UPDATE, DELETE ON public.task_lists, public.tasks TO authenticated;
REVOKE ALL ON FUNCTION public.get_task_watcher_directory(), public.get_task_list_department_directory() FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.get_task_watcher_directory(), public.get_task_list_department_directory() TO authenticated;
GRANT EXECUTE ON FUNCTION public.can_view_task_list(uuid,uuid), public.can_add_task_to_list(uuid,uuid) TO authenticated;
REVOKE ALL ON FUNCTION public.create_task_list_for_user(text,uuid[],uuid,boolean,uuid[],uuid[],text,text,boolean,boolean) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.create_task_list_for_user(text,uuid[],uuid,boolean,uuid[],uuid[],text,text,boolean,boolean) TO authenticated;
REVOKE ALL ON FUNCTION public.admin_can_read_all_profiles() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.admin_can_read_all_profiles() TO authenticated;
REVOKE ALL ON FUNCTION public.archive_completed_tasks() FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.archive_completed_tasks() TO service_role;
REVOKE ALL ON FUNCTION public.can_view_employees_radar(uuid), public.get_employees_radar(date) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.can_view_employees_radar(uuid), public.get_employees_radar(date) TO authenticated;
REVOKE ALL ON FUNCTION public.can_access_crm(uuid), public.is_mq07_design_list(uuid,uuid) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.can_access_crm(uuid), public.is_mq07_design_list(uuid,uuid) TO authenticated;
GRANT SELECT, INSERT, UPDATE, DELETE ON public.crm_clients, public.crm_deals TO authenticated;
GRANT SELECT, INSERT ON public.crm_deal_activity TO authenticated;
GRANT SELECT, INSERT, DELETE ON public.crm_deal_attachments TO authenticated;
GRANT SELECT ON public.crm_deal_approval_steps, public.crm_design_task_approval_steps TO authenticated;
REVOKE ALL ON FUNCTION public.can_assign_tasks_company_wide(uuid), public.can_view_company_employee_names(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.can_assign_tasks_company_wide(uuid), public.can_view_company_employee_names(uuid) TO authenticated;
REVOKE ALL ON FUNCTION public.can_view_all_attendance(uuid), public.is_valid_attendance_coordinates(text), public.can_manage_attendance_records(uuid), public.is_valid_google_maps_location(text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.can_view_all_attendance(uuid), public.is_valid_attendance_coordinates(text), public.can_manage_attendance_records(uuid), public.is_valid_google_maps_location(text) TO authenticated;
GRANT EXECUTE ON FUNCTION public.is_valid_attendance_coordinates(text), public.is_valid_google_maps_location(text) TO service_role;
REVOKE ALL ON FUNCTION public.can_manage_hr_suite_beta(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.can_manage_hr_suite_beta(uuid) TO authenticated, service_role;
GRANT SELECT, INSERT, UPDATE ON public.hr_suite_beta_items TO authenticated;
REVOKE ALL ON FUNCTION public.can_delete_crm_deal(uuid), public.delete_crm_deal(uuid) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.can_delete_crm_deal(uuid), public.delete_crm_deal(uuid) TO authenticated;
REVOKE ALL ON FUNCTION public.admin_delete_employee_request(text,uuid), public.is_employee_request_admin(uuid), public.email_profile_name(uuid) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.admin_delete_employee_request(text,uuid), public.is_employee_request_admin(uuid), public.email_profile_name(uuid) TO authenticated;
REVOKE ALL ON public.project_todos FROM PUBLIC, authenticated;
GRANT SELECT ON public.project_todos TO authenticated;
REVOKE ALL ON FUNCTION public.can_manage_project_todos(uuid,uuid), public.is_project_todo_assignee_eligible(uuid), public.add_project_todo(uuid,text,uuid[],timestamptz), public.set_project_todo_completed(uuid,boolean), public.delete_project_todo(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.can_manage_project_todos(uuid,uuid), public.is_project_todo_assignee_eligible(uuid), public.add_project_todo(uuid,text,uuid[],timestamptz), public.set_project_todo_completed(uuid,boolean), public.delete_project_todo(uuid) TO authenticated;
REVOKE SELECT ON public.crm_deals, public.projects FROM authenticated;
REVOKE ALL ON FUNCTION public.can_view_business_financials(uuid), public.list_crm_deals_secure(), public.list_accessible_projects_secure() FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.can_view_business_financials(uuid), public.list_crm_deals_secure(), public.list_accessible_projects_secure() TO authenticated;
GRANT UPDATE ON public.crm_deal_attachments, public.task_attachments TO authenticated;
REVOKE ALL ON FUNCTION public.can_manage_task_attachments(uuid,uuid), public.archive_crm_deal_attachments(uuid,text[],uuid[]), public.archive_task_attachments(uuid,uuid[]), public.set_project_attachment_visibility(text,uuid,boolean), public.list_project_shared_attachments(uuid) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.can_manage_task_attachments(uuid,uuid), public.archive_crm_deal_attachments(uuid,text[],uuid[]), public.archive_task_attachments(uuid,uuid[]), public.set_project_attachment_visibility(text,uuid,boolean), public.list_project_shared_attachments(uuid) TO authenticated;
REVOKE ALL ON FUNCTION public.validate_shared_attachment_metadata() FROM PUBLIC, anon, authenticated;
REVOKE ALL ON FUNCTION public.change_crm_deal_stage(uuid,text), public.mark_crm_deal_lost(uuid,text), public.change_task_status(uuid,text), public.assign_task(uuid,uuid[]), public.change_project_status(uuid,text), public.assign_project_team(uuid,uuid,uuid[]), public.create_project_update_secure(uuid,text,text), public.start_deal_approval(uuid,uuid,uuid,uuid), public.finalize_crm_deal_approval(uuid) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.change_crm_deal_stage(uuid,text), public.mark_crm_deal_lost(uuid,text), public.change_task_status(uuid,text), public.assign_task(uuid,uuid[]), public.change_project_status(uuid,text), public.assign_project_team(uuid,uuid,uuid[]), public.create_project_update_secure(uuid,text,text), public.start_deal_approval(uuid,uuid,uuid,uuid), public.finalize_crm_deal_approval(uuid) TO authenticated;
REVOKE INSERT, UPDATE, DELETE ON public.tasks FROM authenticated;
REVOKE ALL ON FUNCTION public.can_access_task(uuid,uuid), public.can_manage_task(uuid,uuid), public.list_accessible_tasks_secure(), public.get_task_secure(uuid), public.create_task_secure(jsonb), public.update_task_secure(uuid,jsonb), public.delete_task_secure(uuid), public.add_task_comment(uuid,text,jsonb), public.update_task_comment(uuid,text,jsonb), public.delete_task_comment(uuid), public.list_task_comments_secure(uuid), public.register_task_attachment(uuid,text,text,text,bigint,text,boolean), public.list_task_attachments_secure(uuid,text), public.remove_task_attachment(uuid), public.list_task_activity_secure(uuid) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.can_access_task(uuid,uuid), public.can_manage_task(uuid,uuid), public.list_accessible_tasks_secure(), public.get_task_secure(uuid), public.create_task_secure(jsonb), public.update_task_secure(uuid,jsonb), public.delete_task_secure(uuid), public.add_task_comment(uuid,text,jsonb), public.update_task_comment(uuid,text,jsonb), public.delete_task_comment(uuid), public.list_task_comments_secure(uuid), public.register_task_attachment(uuid,text,text,text,bigint,text,boolean), public.list_task_attachments_secure(uuid,text), public.remove_task_attachment(uuid), public.list_task_activity_secure(uuid) TO authenticated;
GRANT SELECT ON public.task_activity TO authenticated;
REVOKE ALL ON public.projects, public.project_updates, public.project_todos FROM authenticated;
GRANT EXECUTE ON FUNCTION public.create_project_secure(jsonb), public.update_project_secure(uuid,jsonb), public.delete_project_secure(uuid), public.list_project_updates_secure(uuid), public.list_project_todos_secure(uuid), public.get_project_detail_secure(uuid) TO authenticated;
REVOKE ALL ON FUNCTION public.create_project_secure(jsonb), public.update_project_secure(uuid,jsonb), public.delete_project_secure(uuid), public.list_project_updates_secure(uuid), public.list_project_todos_secure(uuid), public.get_project_detail_secure(uuid) FROM PUBLIC, anon;
REVOKE ALL ON FUNCTION public.queue_task_status_notification() FROM PUBLIC, anon, authenticated;
COMMIT;
